{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "In rabbits, [14C]dalbavancin-derived radioactivity in CSF was very low and measurable only at 12 and 24 h postdose, indicating impermeable BBB permeability; dalbavancin is the closest glycopeptide analogue (Morgan 0.5966) and directly supports poor CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Oritavancin, a related lipoglycopeptide, showed CSF penetration of only ~5% of plasma levels in a rabbit meningitis model; even with inflamed meninges, CNS exposure remained minimal, reinforcing the class-level poor BBB penetration expected for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large, heavily glycosylated lipoglycopeptide antibiotic. Direct experimental data on the closest analogues—dalbavancin (CSF radioactivity negligible) and oritavancin (CSF/plasma 1–5% even in meningitis)—consistently demonstrate inadequate CNS access. Low-similarity small-molecule glycoside positives are not transferable because of major scaffold and size differences. Therefore the query is predicted to lack meaningful CNS access.",
  "evidence_gaps": [
    "No direct CSF or brain concentration measurement for the exact query molecule.",
    "No human CNS pharmacokinetic data for the query or its closest analogues.",
    "Exact structural identity/analogue relationship of the query to dalbavancin versus oritavancin is not fully specified.",
    "Contribution of active efflux versus passive permeability was not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

